-- SH | Budžets bez Apps Script: tāmes, versijas, žurnāls, veidnes D1 (agrāk «Budžets · …» lapas). Dzēšana = statuss «Dzēsts» (dati paliek). © VAITKEVIX, SIA
CREATE TABLE IF NOT EXISTS budz_budget (id TEXT PRIMARY KEY, nosaukums TEXT NOT NULL DEFAULT '', adrese TEXT NOT NULL DEFAULT '', pasutitajs TEXT NOT NULL DEFAULT '', izpilditajs TEXT NOT NULL DEFAULT '',
  sagatavots TEXT NOT NULL DEFAULT '', derigs TEXT NOT NULL DEFAULT '', autors TEXT NOT NULL DEFAULT '', statuss TEXT NOT NULL DEFAULT 'Melnraksts', bez_pvn REAL NOT NULL DEFAULT 0, ar_pvn REAL NOT NULL DEFAULT 0,
  versija INTEGER NOT NULL DEFAULT 1, izveidots TEXT NOT NULL DEFAULT '', atjaunots TEXT NOT NULL DEFAULT '', komentars TEXT NOT NULL DEFAULT '', izskatija TEXT NOT NULL DEFAULT '', dati TEXT NOT NULL DEFAULT '{}',
  plat REAL NOT NULL DEFAULT 0, serija TEXT NOT NULL DEFAULT '', ord INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS budz_ver (n INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL, versija INTEGER NOT NULL DEFAULT 1, laiks TEXT NOT NULL DEFAULT '', lietotajs TEXT NOT NULL DEFAULT '',
  statuss TEXT NOT NULL DEFAULT '', bez_pvn REAL NOT NULL DEFAULT 0, piezime TEXT NOT NULL DEFAULT '', dati TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS budz_ver_id ON budz_ver (id, versija);
CREATE TABLE IF NOT EXISTS budz_log (n INTEGER PRIMARY KEY AUTOINCREMENT, laiks TEXT NOT NULL, lietotajs TEXT NOT NULL DEFAULT '', darbiba TEXT NOT NULL DEFAULT '', budzets TEXT NOT NULL DEFAULT '', info TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS budz_tpl (id TEXT PRIMARY KEY, nosaukums TEXT NOT NULL DEFAULT '', apraksts TEXT NOT NULL DEFAULT '', autors TEXT NOT NULL DEFAULT '', izveidots TEXT NOT NULL DEFAULT '', dati TEXT NOT NULL DEFAULT '{}', aktivs INTEGER NOT NULL DEFAULT 1);
